CREATE OR REPLACE FUNCTION public.complete_line_link(p_nonce_hash text, p_line_user_id text, p_success boolean)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare pending public.line_link_requests; existing public.line_connections;
begin
  perform pg_advisory_xact_lock(hashtextextended('line-account-link',0));
  select * into pending from public.line_link_requests where nonce_hash=p_nonce_hash for update;
  if not found then return 'used_or_unknown'; end if;
  delete from public.line_link_requests where ticket_hash=pending.ticket_hash;
  if not p_success or pending.user_id is null or pending.expires_at<=now() or pending.line_user_id<>p_line_user_id then return 'invalid'; end if;
  -- Unique constraints and this lock keep simultaneous link attempts atomic.
  if exists(select 1 from public.line_connections where (user_id=pending.user_id and line_user_id<>p_line_user_id) or (line_user_id=p_line_user_id and user_id<>pending.user_id)) then return 'conflict'; end if;
  insert into public.line_connections(user_id,line_user_id) values(pending.user_id,p_line_user_id)
  on conflict(user_id) do update set active=true, linked_at=now();
  return 'linked';
end $function$

CREATE OR REPLACE FUNCTION public.preserve_job_pay_guarantee()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if TG_OP = 'INSERT' and NEW.pay_guarantee is null then
  raise exception '給与保証の条件を選択してください。';
 end if;
 if TG_OP = 'UPDATE' and NEW.pay_guarantee is distinct from OLD.pay_guarantee
  and exists(select 1 from public.applications where job_id=OLD.id) then
  raise exception '応募者がいる求人の給与保証条件は変更できません。新しい求人で設定してください。';
 end if;
 return NEW;
end $function$

CREATE OR REPLACE FUNCTION public.prevent_overlapping_driver_application()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  j record;
  conflict_job record;
begin
  if new.status not in ('応募中','採用候補','採用','勤務確定') then return new; end if;
  select id, work_date, start_time, end_time into j from jobs where id=new.job_id;
  if j.id is null or j.work_date is null or j.start_time is null or j.end_time is null then return new; end if;
  select j2.id, j2.job_description, j2.work_date, j2.start_time, j2.end_time
    into conflict_job
  from applications a
  join jobs j2 on j2.id=a.job_id
  where a.driver_id=new.driver_id
    and a.id is distinct from new.id
    and a.status in ('応募中','採用候補','採用','勤務確定')
    and j2.status is distinct from 'キャンセル'
    and j2.work_date=j.work_date
    and j2.start_time < j.end_time
    and j2.end_time > j.start_time
  limit 1;
  if conflict_job.id is not null then
    raise exception using
      errcode='P0001',
      message='この時間帯は別の求人に応募済みです。重複する求人には応募できません。';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_job_draft(p_draft_id uuid, p_job jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare d public.job_drafts; job_id bigint;
begin
 if auth.uid() is null then raise exception 'Login required';end if;
 select * into d from public.job_drafts where id=p_draft_id for update;
 if not found then raise exception 'Draft not found or already published';end if;
 if not exists(select 1 from public.companies c where c.id=d.company_id and c.user_id=auth.uid()) then raise exception 'Forbidden';end if;
 insert into public.jobs(company_id,job_description,job_detail,location,destination,access_note,work_prefecture,work_municipality,work_date,start_time,end_time,break_minutes,required_headcount,pay_guarantee,pay_type,pay_amount,transportation_fee,transportation_fee_type,required_license,required_experience,vehicle_type,notes,status)
 values(d.company_id,p_job->>'job_description',p_job->>'job_detail',p_job->>'location',p_job->>'destination',p_job->>'access_note',p_job->>'work_prefecture',p_job->>'work_municipality',(p_job->>'work_date')::date,(p_job->>'start_time')::time,(p_job->>'end_time')::time,(p_job->>'break_minutes')::integer,(p_job->>'required_headcount')::integer,(p_job->>'pay_guarantee')::boolean,p_job->>'pay_type',(p_job->>'pay_amount')::numeric,(p_job->>'transportation_fee')::integer,p_job->>'transportation_fee_type',p_job->>'required_license',p_job->>'required_experience',p_job->>'vehicle_type',p_job->>'notes','募集中')
 returning id into job_id;
 delete from public.job_drafts where id=d.id;
 return job_id;
end $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_driver_preferences(p_profile jsonb, p_line jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); n integer; suffix text; pref text; mun text;
begin
 if v_uid is null then raise exception 'Authentication required'; end if;
 if jsonb_typeof(p_profile) is distinct from 'object' or jsonb_typeof(p_line) is distinct from 'object' then raise exception 'Invalid preferences'; end if;
 if coalesce(trim(p_profile->>'name'),'')='' or coalesce(trim(p_profile->>'phone'),'')='' then raise exception 'Name and phone required'; end if;
 for n in 1..3 loop
  suffix := case when n=1 then '' else '_'||n end;
  pref := nullif(p_profile->>('preferred_prefecture'||suffix),'');
  mun := nullif(p_profile->>('preferred_municipality'||suffix),'');
  if (pref is null) <> (mun is null) then raise exception 'Incomplete location'; end if;
 end loop;
 if jsonb_typeof(p_line->'job_match') is distinct from 'boolean' or jsonb_typeof(p_line->'application_result') is distinct from 'boolean' or jsonb_typeof(p_line->'work_reminder') is distinct from 'boolean' then raise exception 'Invalid LINE settings'; end if;
 update public.drivers set
  name=trim(p_profile->>'name'),
  name_kana=case when p_profile ? 'name_kana' then nullif(trim(p_profile->>'name_kana'),'') else name_kana end,
  phone=trim(p_profile->>'phone'),
  preferred_area=nullif(p_profile->>'preferred_municipality',''),
  preferred_prefecture=nullif(p_profile->>'preferred_prefecture',''),preferred_municipality=nullif(p_profile->>'preferred_municipality',''),
  preferred_prefecture_2=nullif(p_profile->>'preferred_prefecture_2',''),preferred_municipality_2=nullif(p_profile->>'preferred_municipality_2',''),
  preferred_prefecture_3=nullif(p_profile->>'preferred_prefecture_3',''),preferred_municipality_3=nullif(p_profile->>'preferred_municipality_3',''),
  preferred_email_enabled_1=coalesce((p_profile->>'preferred_email_enabled_1')::boolean,preferred_email_enabled_1),
  preferred_line_enabled_1=coalesce((p_profile->>'preferred_line_enabled_1')::boolean,preferred_line_enabled_1),
  preferred_email_enabled_2=coalesce((p_profile->>'preferred_email_enabled_2')::boolean,preferred_email_enabled_2),
  preferred_line_enabled_2=coalesce((p_profile->>'preferred_line_enabled_2')::boolean,preferred_line_enabled_2),
  preferred_email_enabled_3=coalesce((p_profile->>'preferred_email_enabled_3')::boolean,preferred_email_enabled_3),
  preferred_line_enabled_3=coalesce((p_profile->>'preferred_line_enabled_3')::boolean,preferred_line_enabled_3),
  match_email_enabled=(p_profile->>'match_email_enabled')::boolean,
  preferred_vehicle_types=array(select jsonb_array_elements_text(p_profile->'preferred_vehicle_types')),
  preferred_weekdays=array(select x::integer from jsonb_array_elements_text(p_profile->'preferred_weekdays') x),
  preferred_time_slots=array(select jsonb_array_elements_text(p_profile->'preferred_time_slots')),
  license_type=p_profile->>'license_type',experience=p_profile->>'experience'
 where user_id=v_uid;
 if not found then raise exception 'Driver profile not found'; end if;
 insert into public.line_notification_preferences(user_id,job_match,application_result,work_reminder)
 values(v_uid,(p_line->>'job_match')::boolean,(p_line->>'application_result')::boolean,(p_line->>'work_reminder')::boolean)
 on conflict(user_id) do update set job_match=excluded.job_match,application_result=excluded.application_result,work_reminder=excluded.work_reminder;
end;$function$

CREATE OR REPLACE FUNCTION public.scan_driver_attendance(p_token uuid, p_action text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c_id bigint;
  d_id bigint;
  a public.applications%rowtype;
begin
  if p_action not in ('in','out') then raise exception '打刻種別が不正です'; end if;
  select id into c_id from public.companies where user_id=auth.uid();
  if c_id is null then raise exception '企業アカウントでログインしてください'; end if;
  select id into d_id from public.drivers where attendance_token=p_token;
  if d_id is null then raise exception '無効なドライバーQRコードです'; end if;

  if p_action='in' then
    select ap.* into a
    from public.applications ap
    join public.jobs j on j.id=ap.job_id
    where ap.driver_id=d_id
      and j.company_id=c_id
      and ap.status='勤務確定'
      and ap.checked_in_at is null
      and j.work_date=(now() at time zone 'Asia/Tokyo')::date
    order by abs(extract(epoch from (((j.work_date + j.start_time) at time zone 'Asia/Tokyo') - now()))), ap.id desc
    limit 1 for update of ap;
    if not found then raise exception '本日この会社で出勤待ちの勤務がありません'; end if;
    update public.applications set checked_in_at=now(),attendance_method='qr' where id=a.id;
    return '出勤を記録しました';
  else
    select ap.* into a
    from public.applications ap
    join public.jobs j on j.id=ap.job_id
    where ap.driver_id=d_id
      and j.company_id=c_id
      and ap.status='勤務確定'
      and ap.checked_in_at is not null
      and ap.checked_out_at is null
    order by ap.checked_in_at desc, ap.id desc
    limit 1 for update of ap;
    if not found then raise exception '退勤待ちの勤務がありません。先に出勤打刻をしてください'; end if;
    update public.applications set checked_out_at=now(),attendance_method='qr',status='勤務完了',completed_at=coalesce(completed_at,now()) where id=a.id;
    return '退勤を記録し、勤務完了にしました';
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.unlink_line_account(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform pg_advisory_xact_lock(hashtextextended('line-account-link',0));
  delete from public.line_link_requests where user_id=p_user_id;
  delete from public.line_connections where user_id=p_user_id;
end $function$

CREATE OR REPLACE FUNCTION spodora_private.line_application_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j record; driver_user uuid; company_user uuid;
begin
 select * into j from public.jobs where id=new.job_id;
 select user_id into driver_user from public.drivers where id=new.driver_id;
 select user_id into company_user from public.companies where id=j.company_id;
 if tg_op='INSERT' then
 perform spodora_private.enqueue_line(company_user,'new_application','application:'||new.id,
 '【スポドラ】求人に新しい応募が届きました。'||E'\n'||left(coalesce(j.job_description,'ドライバー求人'),200)||E'\n勤務日：'||j.work_date||E'\n応募者の確認：https://spodora.com/company-applicants.html',j.id,new.id);
 elsif new.status is distinct from old.status and new.status in ('採用','勤務確定','不採用','見送り') then
 if new.status='勤務確定' and old.status='採用' then return new; end if;
 perform spodora_private.enqueue_line(driver_user,'application_result','result:'||new.id||':'||case when new.status in ('不採用','見送り') then 'rejected' else 'hired' end,
 '【スポドラ】'||case when new.status='見送り' then '選考結果：今回は見送りとなりました。' else '採用が確定しました。勤務日時・場所をご確認ください。' end||E'\n'||left(coalesce(j.job_description,'ドライバー求人'),200)||E'\n勤務日：'||j.work_date||E'\n確認：https://spodora.com/driver.html',j.id,new.id);
 end if;
 return new;
end;$function$

CREATE OR REPLACE FUNCTION spodora_private.capture_application_pay_guarantee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if TG_OP='INSERT' then
  if auth.uid() is null or not exists(select 1 from public.drivers where id=NEW.driver_id and user_id=auth.uid()) then
   raise exception 'ドライバー本人のログインが必要です。';
  end if;
  select pay_guarantee into NEW.pay_guarantee_snapshot from public.jobs where id=NEW.job_id for share;
  if not found then raise exception '求人が見つかりません。'; end if;
 elsif NEW.pay_guarantee_snapshot is distinct from OLD.pay_guarantee_snapshot or NEW.job_id is distinct from OLD.job_id then
  raise exception '応募時の給与条件と求人は変更できません。';
 end if;
 return NEW;
end $function$

CREATE OR REPLACE FUNCTION spodora_private.request_attendance_review(p_application_id bigint, p_checked_in_at timestamp with time zone, p_checked_out_at timestamp with time zone, p_break_minutes integer, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.applications%rowtype; j public.jobs%rowtype; result_id uuid;
begin
 if auth.uid() is null then raise exception 'ログインしてください。'; end if;
 select ap.* into a from public.applications ap join public.drivers d on d.id=ap.driver_id
 where ap.id=p_application_id and d.user_id=auth.uid() for update of ap;
 if not found then raise exception 'この勤務を申請する権限がありません。'; end if;
 select * into j from public.jobs where id=a.job_id;
 if a.status not in ('勤務確定','勤務完了') or j.status='キャンセル' then raise exception 'この勤務は申請できません。'; end if;
 if p_checked_in_at is null or p_checked_out_at is null or p_checked_out_at<=p_checked_in_at
 or p_checked_out_at-p_checked_in_at>interval '24 hours' or p_checked_out_at>now()+interval '5 minutes'
 or (p_checked_in_at at time zone 'Asia/Tokyo')::date not between j.work_date and j.work_date+1
 then raise exception '実際の出退勤日時を確認してください（勤務日から24時間以内）。'; end if;
 if p_break_minutes is null or p_break_minutes<0 or p_break_minutes*60>extract(epoch from p_checked_out_at-p_checked_in_at) then raise exception '実際の休憩時間を確認してください。'; end if;
 if length(trim(coalesce(p_reason,''))) not between 1 and 1000 then raise exception '確認・修正の理由を1〜1000文字で入力してください。'; end if;
 if exists(select 1 from public.attendance_review_requests where application_id=a.id and status='pending') then raise exception '申請中です。企業の確認をお待ちください。'; end if;
 insert into public.attendance_review_requests(application_id,requested_by,requested_in,requested_out,break_minutes,reason,original_in,original_out,job_context)
 values(a.id,auth.uid(),p_checked_in_at,p_checked_out_at,p_break_minutes,trim(p_reason),a.checked_in_at,a.checked_out_at,spodora_private.attendance_job_context(j,a.pay_guarantee_snapshot))
 returning id into result_id;
 return result_id;
end $function$

CREATE OR REPLACE FUNCTION spodora_private.guard_account_portal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' and new.user_id is distinct from old.user_id then
  raise exception 'account_owner_cannot_change' using errcode='23514';
 end if;
 if current_setting('role',true)='authenticated' and new.user_id is distinct from auth.uid() then
  raise exception 'account_owner_mismatch' using errcode='42501';
 end if;
 -- Serialize competing driver/company registrations for the same auth user.
 perform 1 from auth.users where id=new.user_id for update;
 if tg_table_name='drivers' then
  if exists(select 1 from public.companies where user_id=new.user_id)
   and not exists(select 1 from public.drivers where user_id=new.user_id) then
   raise exception 'separate_account_required' using errcode='23514';
  end if;
 elsif tg_table_name='companies' then
  if exists(select 1 from public.drivers where user_id=new.user_id)
   and not exists(select 1 from public.companies where user_id=new.user_id) then
   raise exception 'separate_account_required' using errcode='23514';
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION spodora_private.decide_attendance_review(p_request_id uuid, p_approve boolean, p_comment text, p_pay_guarantee boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.attendance_review_requests%rowtype; a public.applications%rowtype; j public.jobs%rowtype; policy boolean; planned numeric; worked numeric; amount numeric; planned_amount numeric;
begin
 if auth.uid() is null or p_approve is null then raise exception '企業のログインが必要です。'; end if;
 -- Lock application first, in the same order as the request function.
 select ap.* into a from public.applications ap join public.jobs jo on jo.id=ap.job_id join public.companies c on c.id=jo.company_id
 join public.attendance_review_requests req on req.application_id=ap.id
 where req.id=p_request_id and c.user_id=auth.uid() for update of ap;
 if not found then raise exception 'この申請を確認する権限がありません。'; end if;
 select * into r from public.attendance_review_requests where id=p_request_id for update;
 if r.status<>'pending' then raise exception 'この申請は確認済みです。'; end if;
 if length(coalesce(p_comment,''))>1000 then raise exception 'コメントは1000文字以内で入力してください。'; end if;
 if not p_approve then
  if trim(coalesce(p_comment,''))='' then raise exception '差し戻し理由を入力してください。'; end if;
  update public.attendance_review_requests set status='rejected',reviewed_at=now(),reviewed_by=auth.uid(),review_comment=trim(p_comment) where id=r.id;
  return;
 end if;
 if r.driver_confirmed_at is null or r.requested_transportation_fee is null or r.requested_pay_guarantee is null then raise exception 'ドライバーの交通費確認が必要です。差し戻して、画面を開き直して再申請してください。'; end if;
 select * into j from public.jobs where id=a.job_id for share;
 if a.status not in ('勤務確定','勤務完了') or j.status='キャンセル' then raise exception 'この勤務は承認できません。'; end if;
 if a.checked_in_at is distinct from r.original_in or a.checked_out_at is distinct from r.original_out
 or spodora_private.attendance_job_context(j,a.pay_guarantee_snapshot) is distinct from r.job_context
 then raise exception '申請後に勤怠または求人条件が変わりました。差し戻して再申請してください。'; end if;
 policy=coalesce(a.pay_guarantee_snapshot,r.requested_pay_guarantee);
 if p_pay_guarantee is not null and policy is distinct from p_pay_guarantee then raise exception 'ドライバーが確認した給与保証の条件と異なります。'; end if;
 if policy is null then raise exception '給与保証の条件が未設定です。ドライバーと確認し、承認時の給与条件を選択してください。'; end if;
 planned=extract(epoch from j.end_time-j.start_time);
 if planned<0 then planned=planned+86400; end if;
 planned=planned-j.break_minutes*60;
 worked=extract(epoch from r.requested_out-r.requested_in)-r.break_minutes*60;
 if j.pay_amount is null or j.pay_amount<0 or j.pay_type not in ('時給','日給') or planned is null or planned<=0 then raise exception '求人の勤務時間・給与設定を確認してください。'; end if;
 if j.pay_type='時給' then
  amount=round(j.pay_amount*worked/3600); planned_amount=round(j.pay_amount*planned/3600);
 else
  amount=round(j.pay_amount*worked/planned); planned_amount=j.pay_amount;
 end if;
 if policy then amount=greatest(amount,planned_amount); end if;
 perform public.company_manual_attendance(a.id,r.requested_in,r.requested_out,'勤怠申請承認：'||r.reason);
 update public.applications set status='勤務完了',attendance_review_status='承認済み',attendance_reviewed_at=now(),attendance_reviewed_by=auth.uid() where id=a.id;
 update public.attendance_review_requests set status='approved',reviewed_at=now(),reviewed_by=auth.uid(),review_comment=nullif(trim(p_comment),''),
 effective_pay_guarantee=policy,approved_work_seconds=worked,approved_basic_amount=amount,approved_transportation_fee=r.requested_transportation_fee,approved_total_amount=amount+r.requested_transportation_fee where id=r.id;
end $function$

CREATE OR REPLACE FUNCTION spodora_private.attendance_company_qr(p_regenerate boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.companies%rowtype;
begin
 select * into c from public.companies where user_id=auth.uid() for update;
 if not found then raise exception '企業アカウントでログインしてください'; end if;
 if c.attendance_token is null or p_regenerate then
  update public.companies set attendance_token=gen_random_uuid() where id=c.id returning * into c;
 end if;
 return jsonb_build_object('company_name',c.company_name,'token',c.attendance_token);
end $function$

CREATE OR REPLACE FUNCTION spodora_private.line_job_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d record; v text; slot text;
begin
 if new.status<>'募集中' or new.work_date<(now() at time zone 'Asia/Tokyo')::date or coalesce(new.visibility,'公開') not in ('all','公開','public','') then return new; end if;
 if tg_op='UPDATE' and old.status='募集中' then return new; end if;
 v:=case new.vehicle_type when '2tトラック' then '2t' when '4tトラック' then '4t' else new.vehicle_type end;
 slot:=case when extract(hour from new.start_time)<6 then 'early' when extract(hour from new.start_time)<12 then 'morning' when extract(hour from new.start_time)<18 then 'afternoon' else 'evening' end;
 for d in select x.* from public.drivers x join public.line_connections c on c.user_id=x.user_id and c.active
 where not coalesce(x.is_paused,false) and spodora_private.driver_job_area_matches(x,new,'line')
 and (coalesce(cardinality(x.preferred_vehicle_types),0)=0 or v=any(x.preferred_vehicle_types))
 and (coalesce(cardinality(x.preferred_weekdays),0)=0 or extract(dow from new.work_date)::integer=any(x.preferred_weekdays))
 and (coalesce(cardinality(x.preferred_time_slots),0)=0 or slot=any(x.preferred_time_slots))
 and not exists(select 1 from public.company_driver_blocks b where b.company_id=new.company_id and b.driver_id=x.id)
 loop
 perform spodora_private.enqueue_line(d.user_id,'job_match','job:'||new.id,
 '【スポドラ】希望条件に合う新しい求人が掲載されました。'||E'\n'||left(coalesce(new.job_description,'ドライバー求人'),200)||E'\n勤務日：'||new.work_date||E'\n勤務地：'||coalesce(new.work_prefecture,'')||' '||coalesce(new.work_municipality,'')||E'\n詳細・応募：https://spodora.com/driver.html',new.id);
 end loop;
 return new;
end;$function$

CREATE OR REPLACE FUNCTION spodora_reviews.submit_work_review(p_application_id bigint, p_side text, p_rating integer, p_comment text DEFAULT ''::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_driver uuid;v_company uuid;v_status text;v_out timestamptz;v_job_status text;v_id bigint;v_comment text:=btrim(coalesce(p_comment,''));
begin
 if v_actor is null then raise exception 'ログインしてください。' using errcode='42501';end if;
 if p_side not in ('company','driver') or p_side is null or p_rating is null or p_rating<1 or p_rating>5 or char_length(v_comment)>1000 then raise exception '評価は1〜5、コメントは1000文字以内で入力してください。' using errcode='22023';end if;
 select d.user_id,c.user_id,a.status,a.checked_out_at,j.status into v_driver,v_company,v_status,v_out,v_job_status
 from public.applications a join public.jobs j on j.id=a.job_id join public.drivers d on d.id=a.driver_id join public.companies c on c.id=j.company_id where a.id=p_application_id for update of a;
 if not found or (p_side='company' and v_company is distinct from v_actor) or (p_side='driver' and v_driver is distinct from v_actor) then raise exception 'この勤務を評価できません。' using errcode='42501';end if;
 if v_job_status='キャンセル' or (v_out is null and v_status is distinct from '勤務完了') then raise exception '勤務終了後に評価できます。' using errcode='22023';end if;
 if p_side='company' then
 insert into public.reviews(application_id,driver_rating,company_comment) values(p_application_id,p_rating,v_comment)
 on conflict(application_id) do update set driver_rating=excluded.driver_rating,company_comment=excluded.company_comment returning id into v_id;
 else
 insert into public.reviews(application_id,company_rating,driver_comment) values(p_application_id,p_rating,v_comment)
 on conflict(application_id) do update set company_rating=excluded.company_rating,driver_comment=excluded.driver_comment returning id into v_id;
 end if;
 return v_id;
end$function$

CREATE OR REPLACE FUNCTION spodora_private.finish_confirmed_company_registration()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p jsonb;
begin
 if new.email_confirmed_at is null then return new;end if;
 select profile into p from public.pending_company_registrations where user_id=new.id for update;
 if p is null then return new;end if;
 insert into public.companies(user_id,company_name,contact_name,phone,address,email,acquisition_source,acquisition_medium,acquisition_campaign,acquisition_content,acquisition_ref)
 values(new.id,p->>'company_name',p->>'contact_name',p->>'company_phone',p->>'company_address',new.email,p->>'acquisition_source',p->>'acquisition_medium',p->>'acquisition_campaign',p->>'acquisition_content',p->>'acquisition_ref')
 on conflict(user_id) do nothing;
 delete from public.pending_company_registrations where user_id=new.id;
 return new;
end $function$

CREATE OR REPLACE FUNCTION spodora_private.request_pay_confirmation(p_application_id bigint, p_checked_in_at timestamp with time zone, p_checked_out_at timestamp with time zone, p_break_minutes integer, p_reason text, p_transportation_fee integer, p_pay_guarantee boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result_id uuid; ctx jsonb; expected_fee numeric;
begin
 -- The existing function checks auth.uid(), driver ownership, time bounds and pending duplicates, and locks the application.
 result_id=spodora_private.request_attendance_review(p_application_id,p_checked_in_at,p_checked_out_at,p_break_minutes,p_reason);
 select job_context into ctx from public.attendance_review_requests where id=result_id;
 if p_pay_guarantee is null then raise exception '給与保証の条件を企業と確認し、選択してください。'; end if;
 if ctx->>'pay_guarantee' is not null and p_pay_guarantee<>(ctx->>'pay_guarantee')::boolean then raise exception '応募時の給与保証条件と異なります。'; end if;
 expected_fee=case when ctx->>'transportation_fee_type'='なし' then 0 else (ctx->>'transportation_fee')::numeric end;
 if p_transportation_fee is null or p_transportation_fee<0 or p_transportation_fee>1000000 then raise exception '交通費は0〜100万円の整数で入力してください。'; end if;
 if expected_fee is not null and p_transportation_fee<>expected_fee then raise exception '求人に指定された交通費と異なります。企業に条件を確認してください。'; end if;
 update public.attendance_review_requests set requested_transportation_fee=p_transportation_fee,requested_pay_guarantee=p_pay_guarantee,driver_confirmed_at=now() where id=result_id;
 return result_id;
end $function$

CREATE OR REPLACE FUNCTION spodora_private.company_scan_work(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.companies%rowtype; d bigint; rows jsonb;
begin
 select * into c from public.companies where attendance_token=p_token;
 if not found then raise exception 'このQRは無効です。企業の最新のQRを読み取ってください'; end if;
 select id into d from public.drivers where user_id=auth.uid();
 if d is null then raise exception 'ドライバーとしてログインしてください'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'title',j.job_description,'work_date',j.work_date,'start_time',j.start_time,'end_time',j.end_time,'checked_in_at',a.checked_in_at,'checked_out_at',a.checked_out_at) order by j.work_date,j.start_time,a.id),'[]'::jsonb) into rows
 from public.applications a join public.jobs j on j.id=a.job_id
 where a.driver_id=d and j.company_id=c.id and j.status is distinct from 'キャンセル' and a.status in ('勤務確定','勤務完了')
 and (j.work_date=(now() at time zone 'Asia/Tokyo')::date or (a.checked_in_at is not null and a.checked_out_at is null and a.status='勤務確定'));
 return jsonb_build_object('company_name',c.company_name,'work',rows);
end $function$

CREATE OR REPLACE FUNCTION spodora_private.punch_company_qr(p_token uuid, p_application_id bigint, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c bigint; d bigint; a public.applications%rowtype;
begin
 if p_action is null or p_action not in ('in','out') then raise exception '打刻種別が不正です'; end if;
 -- Serialize with regeneration: an invalidated token cannot commit a later punch.
 select id into c from public.companies where attendance_token=p_token for share;
 if c is null then raise exception 'このQRは無効です。企業の最新のQRを読み取ってください'; end if;
 select id into d from public.drivers where user_id=auth.uid();
 if d is null then raise exception 'ドライバーとしてログインしてください'; end if;
 select ap.* into a from public.applications ap join public.jobs j on j.id=ap.job_id
 where ap.id=p_application_id and ap.driver_id=d and j.company_id=c
 and j.status is distinct from 'キャンセル' and ap.status in ('勤務確定','勤務完了')
 and (j.work_date=(now() at time zone 'Asia/Tokyo')::date or (ap.checked_in_at is not null and ap.checked_out_at is null and ap.status='勤務確定')) for update of ap;
 if not found then raise exception 'この企業で本日打刻できる勤務がありません'; end if;
 if a.checked_out_at is not null then
  return jsonb_build_object('message','すでに退勤済みです','checked_in_at',a.checked_in_at,'checked_out_at',a.checked_out_at,'already_recorded',true);
 end if;
 if p_action='in' then
  if a.checked_in_at is not null then
   return jsonb_build_object('message','すでに出勤済みです','checked_in_at',a.checked_in_at,'already_recorded',true);
  end if;
  if a.status<>'勤務確定' then raise exception 'この勤務は完了しています'; end if;
  update public.applications set checked_in_at=now(),attendance_method='qr' where id=a.id returning * into a;
 else
  if a.checked_in_at is null then raise exception '先に出勤打刻をしてください'; end if;
  update public.applications set checked_out_at=now(),attendance_method='qr',status='勤務完了',completed_at=coalesce(completed_at,now()) where id=a.id returning * into a;
 end if;
 return jsonb_build_object('message',case when p_action='in' then '出勤を記録しました' else '退勤を記録しました' end,'checked_in_at',a.checked_in_at,'checked_out_at',a.checked_out_at,'already_recorded',false);
end $function$

CREATE OR REPLACE FUNCTION spodora_private.queue_company_application_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j record; c record; recipient_email text; driver_name text;
begin
 select id,company_id,job_description,work_date,start_time,end_time into j from public.jobs where id=new.job_id;
 select company_name,user_id,email into c from public.companies where id=j.company_id;
 if c.user_id is null then return new; end if;
 select coalesce(nullif(trim(c.email),''),u.email) into recipient_email from auth.users u where u.id=c.user_id;
 if recipient_email is null or trim(recipient_email)='' or recipient_email like '%@accounts.spodora.invalid' then return new;end if;
 select name into driver_name from public.drivers where id=new.driver_id;
 insert into public.company_application_email_queue(company_id,application_id,job_id,recipient,subject,message)
 values(j.company_id,new.id,j.id,recipient_email,
 '【スポドラ】求人に新しい応募が届きました｜'||left(coalesce(j.job_description,'ドライバー求人'),100),
 coalesce(c.company_name,'企業')||' ご担当者様'||chr(10)||chr(10)||
 '掲載中の求人に新しい応募がありました。'||chr(10)||chr(10)||
 '求人：'||coalesce(j.job_description,'ドライバー求人')||chr(10)||
 '勤務日：'||coalesce(j.work_date::text,'未設定')||chr(10)||
 '勤務時間：'||coalesce(left(j.start_time::text,5),'')||'〜'||coalesce(left(j.end_time::text,5),'')||chr(10)||
 '応募者：'||coalesce(driver_name,'ドライバー')||chr(10)||chr(10)||
 '応募者の確認・選考は企業画面からお願いします。'||chr(10)||
 'https://spodora.com/company-applicants.html'||chr(10)||chr(10)||'スポドラ')
 on conflict(application_id) do nothing;
 return new;
end;
$function$
